#include "Guide.h"
#include "Brand.h"
#include "PluginEditor.h"       // SimpleGainLookAndFeel, for the fonts
#include "BinaryData.h"         // the guide's text, generated by juce_add_binary_data in CMakeLists.txt

namespace
{
    const juce::URL docsLink { "https://github.com/milliedavidson/simply-gain/blob/main/documentation/README.md" };
}


//==============================================================================
namespace guide
{
    std::vector<Block> parse (const juce::String& markdown)
    {
        // An open paragraph or bullet takes the lines that follow it, until a blank line.
        // -> documentation/editor-gui.md section 15
        std::vector<Block> blocks;
        bool open = false;

        for (const auto& line : juce::StringArray::fromLines (markdown))
        {
            const auto trimmed = line.trim();

            if (trimmed.isEmpty())
                open = false;
            else if (trimmed.startsWith ("## "))
                blocks.push_back ({ Block::Kind::heading, trimmed.substring (3).trim() }), open = false;
            else if (trimmed.startsWith ("# "))
                blocks.push_back ({ Block::Kind::title, trimmed.substring (2).trim() }), open = false;
            else if (trimmed.startsWith ("- "))
                blocks.push_back ({ Block::Kind::bullet, trimmed.substring (2).trim() }), open = true;
            else if (open)
                blocks.back().text << " " << trimmed;
            else
                blocks.push_back ({ Block::Kind::paragraph, trimmed }), open = true;
        }

        return blocks;
    }

    juce::AttributedString style (const juce::String& text, const juce::Font& normal, const juce::Font& code,
                                  const juce::Colour normalColour, const juce::Colour strongColour)
    {
        // Walk the text once, switching style at each ** or `, and append each run with its style.
        juce::AttributedString result;
        juce::String run;
        bool strong = false, isCode = false;

        const auto flush = [&]
        {
            if (run.isNotEmpty())
                result.append (run, isCode ? code : normal, strong ? strongColour : normalColour);
            run.clear();
        };

        for (int i = 0; i < text.length(); ++i)
        {
            if (text.substring (i).startsWith ("**"))
                flush(), strong = ! strong, ++i;        // ++i skips the second *
            else if (text[i] == '`')
                flush(), isCode = ! isCode;
            else
                run << juce::String::charToString (text[i]);
        }

        flush();
        return result;
    }

    juce::String quickStart()
    {
        return juce::String::fromUTF8 (BinaryData::quickstart_md, BinaryData::quickstart_mdSize);
    }
}


//==============================================================================
GuidePage::GuidePage (const SimpleGainLookAndFeel& lf)
    : lookAndFeel (lf),
      blocks (guide::parse (guide::quickStart())),
      link ("Read the full documentation online", docsLink)
{
    link.setColour (juce::HyperlinkButton::textColourId, tokens::apricot);
    link.setTitle ("Read the full documentation online");
    addAndMakeVisible (link);
}

void GuidePage::setTextHeight (const float height)
{
    textHeight = height;
}

juce::String GuidePage::getGuideTitle() const
{
    for (const auto& block : blocks)
        if (block.kind == guide::Block::Kind::title)
            return block.text;

    return {};
}

void GuidePage::setWidthAndLayOut (const int width)
{
    // Each block becomes a juce::TextLayout: JUCE wraps it to the width and says how tall it is.
    // Spacing is a fraction of the text's height, so the page scales. -> documentation/editor-gui.md section 15
    const auto body    = juce::Font (lookAndFeel.textFont (textHeight));
    const auto code    = juce::Font (lookAndFeel.monoFont (textHeight * 0.95f));
    const auto heading = juce::Font (lookAndFeel.logoFont (textHeight * 1.3f));
    const auto indent  = textHeight * 1.2f;
    const auto fullWidth = static_cast<float> (width);

    laidOut.clear();
    float y = 0.0f;

    for (const auto& block : blocks)
    {
        if (block.kind == guide::Block::Kind::title)
            continue;                                       // shown above the page instead

        LaidOut item;
        juce::AttributedString text;

        if (block.kind == guide::Block::Kind::heading)
        {
            if (! laidOut.empty())
                y += textHeight;                            // a gap before every heading but the first
            text.append (block.text, heading, tokens::text);
        }
        else
        {
            text = guide::style (block.text, body, code, tokens::text, tokens::apricot);
            text.setLineSpacing (textHeight * 0.3f);
        }

        item.isBullet = block.kind == guide::Block::Kind::bullet;
        const auto x = item.isBullet ? indent : 0.0f;
        item.layout.createLayout (text, fullWidth - x);
        item.at = { x, y };

        y += item.layout.getHeight() + textHeight * (block.kind == guide::Block::Kind::bullet ? 0.45f : 0.7f);
        laidOut.push_back (std::move (item));
    }

    y += textHeight * 0.6f;
    link.setFont (body, false, juce::Justification::centredLeft);
    link.setBounds (0, juce::roundToInt (y), width, juce::roundToInt (textHeight * 1.6f));
    link.changeWidthToFitText();
    y += textHeight * 2.6f;

    setSize (width, juce::roundToInt (y));
}

void GuidePage::paint (juce::Graphics& g)
{
    for (const auto& item : laidOut)
    {
        if (item.isBullet)
        {
            g.setColour (tokens::muted);
            g.setFont (lookAndFeel.textFont (textHeight));
            g.drawText (juce::String::charToString (0x2022), juce::Rectangle<float> (textHeight, textHeight * 1.3f).withPosition (item.at.x - textHeight * 1.1f, item.at.y),
                        juce::Justification::centredLeft);      // U+2022, a bullet
        }

        item.layout.draw (g, juce::Rectangle<float> (item.layout.getWidth(), item.layout.getHeight()).withPosition (item.at));
    }
}


//==============================================================================
GuideView::GuideView (const SimpleGainLookAndFeel& lf)
    : lookAndFeel (lf),
      page (lf)
{
    viewport.setViewedComponent (&page, false);     // false: the viewport borrows the page, it doesn't own it
    viewport.setScrollBarsShown (true, false);      // a vertical bar when the text is too long, never a horizontal one
    viewport.getVerticalScrollBar().setColour (juce::ScrollBar::thumbColourId, tokens::line);
    addAndMakeVisible (viewport);
}

void GuideView::paint (juce::Graphics& g)
{
    // Opaque Base over the controls, and the title just right of the ring mark. -> documentation/editor-gui.md section 15
    g.fillAll (tokens::base);

    const auto height = static_cast<float> (getHeight());
    g.setColour (tokens::text);
    g.setFont (lookAndFeel.logoFont (height * 0.072f));
    g.drawText (page.getGuideTitle(), juce::Rectangle<float> (height * 0.19f, height * 0.05f, static_cast<float> (getWidth()) / 2.0f, height * 0.1f),
                juce::Justification::centredLeft);
}

void GuideView::resized()
{
    // Never smaller than 12 pixels: below that, text stops being comfortable to read.
    const auto height = static_cast<float> (getHeight());
    const auto margin = height * 0.06f;
    const auto scrollBar = juce::jmax (6.0f, height * 0.018f);

    page.setTextHeight (juce::jmax (12.0f, height * 0.042f));
    viewport.setScrollBarThickness (juce::roundToInt (scrollBar));
    viewport.setBounds (juce::Rectangle<float> (margin, height * 0.18f, static_cast<float> (getWidth()) - margin * 1.5f,
                                                height * 0.82f - margin * 0.5f).toNearestInt());
    page.setWidthAndLayOut (viewport.getWidth() - juce::roundToInt (scrollBar + margin * 0.5f));
}
